import os
import importlib.util
import pytest

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
merge_inventory = target.merge_inventory


def test_sums_matching_skus():
    assert merge_inventory({"a": 1, "b": 2}, {"a": 3, "b": 4}) == {"a": 4, "b": 6}


def test_disjoint_skus_are_union():
    assert merge_inventory({"a": 1}, {"b": 2}) == {"a": 1, "b": 2}


def test_empty_inputs():
    assert merge_inventory({}, {}) == {}
    assert merge_inventory({"a": 5}, {}) == {"a": 5}
    assert merge_inventory({}, {"a": 5}) == {"a": 5}


def test_returns_new_dict_and_does_not_mutate_inputs():
    base = {"a": 1}
    incoming = {"a": 2, "b": 3}
    result = merge_inventory(base, incoming)
    assert result is not base
    assert result is not incoming
    assert base == {"a": 1}
    assert incoming == {"a": 2, "b": 3}


def test_zero_counts_allowed():
    assert merge_inventory({"a": 0}, {"a": 0}) == {"a": 0}


def test_negative_count_in_base_rejected():
    with pytest.raises(ValueError):
        merge_inventory({"a": -1}, {})


def test_negative_count_in_incoming_rejected():
    with pytest.raises(ValueError):
        merge_inventory({}, {"a": -1})


def test_non_integer_count_rejected():
    with pytest.raises(TypeError):
        merge_inventory({"a": 1.5}, {})
    with pytest.raises(TypeError):
        merge_inventory({}, {"a": "3"})


def test_non_dict_inputs_rejected():
    with pytest.raises(TypeError):
        merge_inventory(None, {})
    with pytest.raises(TypeError):
        merge_inventory({}, [("a", 1)])


def test_empty_sku_rejected():
    with pytest.raises(ValueError):
        merge_inventory({"": 1}, {})


def test_large_counts():
    big = 10**18
    assert merge_inventory({"a": big}, {"a": big}) == {"a": 2 * big}


def test_multiple_skus_mixed():
    base = {"x": 10, "y": 0, "z": 7}
    incoming = {"y": 5, "z": 1, "w": 2}
    assert merge_inventory(base, incoming) == {"x": 10, "y": 5, "z": 8, "w": 2}

