import os
import importlib.util
TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
unique_preserve_order = target.unique_preserve_order


def test_basic_dedupe_order():
    assert unique_preserve_order(["b", "a", "b", "c", "a"]) == ["b", "a", "c"]


def test_empty_list():
    assert unique_preserve_order([]) == []


def test_case_insensitive_duplicate_removed():
    assert unique_preserve_order(["Apple", "apple"]) == ["Apple"]


def test_case_insensitive_keeps_first_casing():
    assert unique_preserve_order(["Apple", "banana", "APPLE", "Banana"]) == ["Apple", "banana"]


def test_type_error_non_list():
    try:
        unique_preserve_order("abc")
    except TypeError:
        return
    assert False, "expected TypeError"

