import os
import importlib.util
import pytest

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
net_by_account = target.net_by_account


def test_single_transaction():
    assert net_by_account([{"account": "A", "amount": 10.0}]) == {"A": 10.0}


def test_multiple_transactions_same_account_are_summed():
    txs = [
        {"account": "A", "amount": 10.0},
        {"account": "A", "amount": 5.5},
    ]
    assert net_by_account(txs) == {"A": 15.5}


def test_debits_reduce_net():
    txs = [
        {"account": "A", "amount": 20.0},
        {"account": "A", "amount": -7.25},
    ]
    assert net_by_account(txs) == {"A": 12.75}


def test_separate_accounts():
    txs = [
        {"account": "A", "amount": 1.0},
        {"account": "B", "amount": 2.0},
        {"account": "A", "amount": 3.0},
    ]
    assert net_by_account(txs) == {"A": 4.0, "B": 2.0}


def test_empty_list():
    assert net_by_account([]) == {}


def test_rounded_to_two_decimals():
    txs = [
        {"account": "A", "amount": 0.1},
        {"account": "A", "amount": 0.2},
    ]
    assert net_by_account(txs) == {"A": 0.3}


def test_non_list_rejected():
    with pytest.raises(TypeError):
        net_by_account("nope")

